#!/bin/bash
# Reference solution: write generate.sh (which contains a heredoc of its own)
# with an outer heredoc, then run it and compare with the example.
cat > generate.sh <<'SCRIPT'
#!/bin/bash
# generate.sh - build app.conf from the values in vars.env
source ./vars.env
cat > app.conf <<EOF
# app.conf - generated by generate.sh, do not edit by hand
[app]
name = $APP_NAME
environment = $APP_ENV
listen = 0.0.0.0:$APP_PORT
url = http://localhost:$APP_PORT/

[logging]
format = \$remote_addr "\$request" \$status
EOF
SCRIPT
bash generate.sh
diff app.conf app.conf.example && echo "app.conf matches the example"
